# Definition for a binary tree node
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Codec:
    def serialize(self, root):
        """Encodes a tree to a single string."""
        if not root:
            return ""

        # Preorder traversal gives us enough info to reconstruct BST
        values = []

        def preorder(node):
            if node:
                values.append(str(node.val))
                preorder(node.left)
                preorder(node.right)

        preorder(root)
        return ",".join(values)

    def deserialize(self, data):
        """Decodes your encoded data to tree."""
        if not data:
            return None

        values = [int(x) for x in data.split(",")]
        index = [0]  # Use list to make it mutable in nested function

        def build_tree(min_val, max_val):
            if index[0] >= len(values):
                return None

            val = values[index[0]]

            # Check if current value fits in the valid range for BST
            if val < min_val or val > max_val:
                return None

            # Consume the value
            index[0] += 1

            # Build the node and its subtrees
            node = TreeNode(val)
            node.left = build_tree(min_val, val)
            node.right = build_tree(val, max_val)

            return node

        return build_tree(float('-inf'), float('inf'))

# Alternative approach using stack-based deserialization
class CodecStack:
    def serialize(self, root):
        if not root:
            return ""

        result = []
        stack = [root]

        while stack:
            node = stack.pop()
            result.append(str(node.val))

            # Add right first so left is processed first
            if node.right:
                stack.append(node.right)
            if node.left:
                stack.append(node.left)

        return ",".join(result)

    def deserialize(self, data):
        if not data:
            return None

        values = [int(x) for x in data.split(",")]

        def build():
            if not values:
                return None

            root_val = values[0]
            root = TreeNode(root_val)

            # Find boundary between left and right subtrees
            i = 1
            while i < len(values) and values[i] < root_val:
                i += 1

            # Split values for left and right subtrees
            left_values = values[1:i]
            right_values = values[i:]

            # Store remaining values back
            values[:] = []

            # Recursively build subtrees
            if left_values:
                values[:] = left_values
                root.left = build()

            if right_values:
                values[:] = right_values
                root.right = build()

            return root

        return build()

# More efficient iterative deserialization
class CodecIterative:
    def serialize(self, root):
        if not root:
            return ""

        result = []

        def dfs(node):
            if node:
                result.append(str(node.val))
                dfs(node.left)
                dfs(node.right)

        dfs(root)
        return ",".join(result)

    def deserialize(self, data):
        if not data:
            return None

        values = list(map(int, data.split(",")))
        stack = []
        root = None

        for val in values:
            node = TreeNode(val)

            # Find correct position for this node
            last_popped = None

            # Pop nodes that are smaller than current value
            while stack and stack[-1].val < val:
                last_popped = stack.pop()

            if last_popped:
                # Current node goes to right of last popped node
                last_popped.right = node
            elif stack:
                # Current node goes to left of stack top
                stack[-1].left = node
            else:
                # First value: this is the root
                root = node

            stack.append(node)

        return root

# Postorder approach for comparison
class CodecPostorder:
    def serialize(self, root):
        if not root:
            return ""

        result = []

        def postorder(node):
            if node:
                postorder(node.left)
                postorder(node.right)
                result.append(str(node.val))

        postorder(root)
        return ",".join(result)

    def deserialize(self, data):
        if not data:
            return None

        values = [int(x) for x in data.split(",")]
        values.reverse()  # Process from end for postorder
        index = [0]

        def build_tree(min_val, max_val):
            if index[0] >= len(values):
                return None

            val = values[index[0]]

            if val < min_val or val > max_val:
                return None

            index[0] += 1

            # For postorder: build right subtree first, then left
            node = TreeNode(val)
            node.right = build_tree(val, max_val)
            node.left = build_tree(min_val, val)

            return node

        return build_tree(float('-inf'), float('inf'))

# Level order approach (less compact but works)
class CodecLevelOrder:
    def serialize(self, root):
        if not root:
            return ""

        from collections import deque
        queue = deque([root])
        result = []

        while queue:
            node = queue.popleft()
            if node:
                result.append(str(node.val))
                queue.append(node.left)
                queue.append(node.right)
            else:
                result.append("null")

        # Remove trailing nulls
        while result and result[-1] == "null":
            result.pop()

        return ",".join(result)

    def deserialize(self, data):
        if not data:
            return None

        from collections import deque
        values = data.split(",")

        root = TreeNode(int(values[0]))
        queue = deque([root])
        i = 1

        while queue and i < len(values):
            node = queue.popleft()

            # Left child
            if i < len(values) and values[i] != "null":
                node.left = TreeNode(int(values[i]))
                queue.append(node.left)
            i += 1

            # Right child
            if i < len(values) and values[i] != "null":
                node.right = TreeNode(int(values[i]))
                queue.append(node.right)
            i += 1

        return root

