class CodecBinary:
    def serialize(self, root):
        import struct

        if not root:
            return ""

        values = []

        def preorder(node):
            if node:
                values.append(node.val)
                preorder(node.left)
                preorder(node.right)

        preorder(root)

        # Pack integers as binary
        return struct.pack(f'{len(values)}i', *values)

    def deserialize(self, data):
        import struct

        if not data:
            return None

        # Unpack binary data
        values = list(struct.unpack(f'{len(data)//4}i', data))
        index = [0]

        def build_tree(min_val, max_val):
            if index[0] >= len(values):
                return None

            val = values[index[0]]

            if val < min_val or val > max_val:
                return None

            index[0] += 1

            node = TreeNode(val)
            node.left = build_tree(min_val, val)
            node.right = build_tree(val, max_val)

            return node

        return build_tree(float('-inf'), float('inf'))
